export function getPostAttachmentPublicMutationKey() {
  return ['attachment-public', '/attachment-public', 'POST'] as const
}

export function getPostAttachmentPublicMutationOptions<
  TError = DefaultError,
  TOnMutateResult = unknown,
>(options?: ClientRequestOptions) {
  return mutationOptions<
    Awaited<
      ReturnType<
        typeof parseResponse<Awaited<ReturnType<(typeof client)['attachment-public']['$post']>>>
      >
    >,
    TError,
    InferRequestType<(typeof client)['attachment-public']['$post']>,
    TOnMutateResult
  >({
    mutationKey: getPostAttachmentPublicMutationKey(),
    async mutationFn(args: InferRequestType<(typeof client)['attachment-public']['$post']>) {
      return parseResponse(client['attachment-public'].$post(args, options))
    },
  })
}

export function createPostAttachmentPublic<TError = DefaultError, TOnMutateResult = unknown>(
  options?: () => {
    mutation?: Omit<
      ReturnType<
        CreateMutationOptions<
          Awaited<
            ReturnType<
              typeof parseResponse<
                Awaited<ReturnType<(typeof client)['attachment-public']['$post']>>
              >
            >
          >,
          TError,
          InferRequestType<(typeof client)['attachment-public']['$post']>,
          TOnMutateResult
        >
      >,
      'mutationFn'
    >
    options?: ClientRequestOptions
  },
  queryClient?: () => QueryClient,
) {
  return createMutation(() => {
    const { mutation, options: clientOptions } = options?.() ?? {}
    const mutationDefaults = getPostAttachmentPublicMutationOptions<TError, TOnMutateResult>(
      clientOptions,
    )
    return {
      ...mutation,
      ...mutationDefaults,
      mutationKey: mutation?.mutationKey ?? mutationDefaults.mutationKey,
    }
  }, queryClient)
}

